cpp.setup:
auto* control = new fluent::scrolling::ScrollView(%PARENT%);
auto* content = new QWidget(control);
content->setMinimumSize(380, 240);
auto* layout = new QVBoxLayout(content);
for (int i = 1; i <= 5; ++i)
    layout->addWidget(new fluent::textfields::Label(QStringLiteral("Scrollable row %1").arg(i), content));
control->setContentWidget(content);
